(function(root){'use strict';
root.createCashUI=function(host){
 const {state,save,render,openModal,toast,cards,safe}=host,C=root.MesaCash,D=root.MesaCashCoach,E=root.MesaEngine;
 let timer=null,lastFocus=null,paused=false,lastEvent='',ai={status:'idle'},studyRows=[],studyIndex=0,studyAnswer=null,studyScore=0,chartSeat='BTN',chartHand='AKs';
 state.cashArchives ||= [];state.cash ||= C.make();if(!state.cash.currencyVersion){state.cashArchives.push(state.cash);state.cash=C.make(state.cash.config);state.cash.currencyNotice=true;}C.upgrade(state.cash);C.ensureSession(state.cash);state.prefs.cashSpeed ||= 'normal';
 const bb=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const t=()=>state.cash,rounds=()=>D.sampleHands(t()).length,amount=n=>bb(C.bb(n)),unit=n=>'',pct=n=>n===null?'—':Math.round(n*100)+'%',labels={fold:'Desistir',call:'Pagar',check:'Mesa (check)',raise:'Apostar / aumentar'};
 const speeds={slow:1100,normal:620,fast:230,off:0};
 const reduced=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const duration=()=>reduced()?0:speeds[state.prefs.cashSpeed]??620;
 const a=(action,label,cls='outline-btn',extra='')=>`<button class="${cls}" data-do="cash-${action}" ${extra}>${label}</button>`;

 const num=(n,d=1)=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:d});
 const gradeChip=g=>`<span class="grade-chip grade-${g.key}">${g.label}${g.loss?` · −${bb(g.loss)}`:''}</span>`;
 function spotStrip(c){const m=C.spotMetrics(c),chips=[];if(!m)return '';if(m.potOdds!==null)chips.push(['Preço',pct(m.potOdds),'Equidade mínima para pagar, já descontada a taxa estimada']);if(m.betPct!==null)chips.push(['Aposta',pct(m.betPct)+' do pote','Tamanho da aposta que você enfrenta']);if(m.mdf!==null)chips.push(['MDF',pct(m.mdf),'Frequência mínima de defesa contra um adversário']);if(m.spr!==null)chips.push(['SPR',num(m.spr),'Seu saldo dividido pelo pote']);if(m.texture)chips.push(['Board',m.texture.label.replace('Board ',''),m.texture.tags.join(' · ')]);return chips.length?`<div class="spot-strip" aria-label="Números do spot">${chips.map(([k,v,tip])=>`<span title="${tip}"><small>${k}</small><b>${v}</b></span>`).join('')}</div>`:'';}
 function handGrades(h){const rows=(h.decisions||[]).filter(d=>!d.assisted);if(!rows.length)return '';return `<div class="hand-grades" aria-label="Nota das suas decisões nesta mão"><span class="eyebrow">Suas decisões no modelo</span>${rows.map(d=>`<div><small>${E.STREETS[d.context.street]}</small>${gradeChip(C.grade(d))}</div>`).join('')}</div>`;}
 function accuracyPanel(){const x=D.accuracy(t(),C);if(!x.decisions)return '';const order=['best','ok','inaccuracy','mistake','blunder'],row=(name,b)=>`<tr><th scope="row">${name}</th><td>${b.n}</td><td><b class="score-${b.score>=80?'high':b.score>=60?'mid':'low'}">${b.score}</b></td><td>${b.misses}</td><td>${b.loss?'−'+bb(b.loss):'—'}</td></tr>`,positions=['UTG','UTG+1','UTG+2','MP','MP+1','LJ','HJ','CO','BTN'].filter(p=>x.positions[p]);
  return `<section class="content-panel accuracy-panel"><span class="eyebrow">Precisão no modelo · leitura no estilo de ferramentas de estudo</span><div class="accuracy-head"><div class="accuracy-score score-${x.score>=80?'high':x.score>=60?'mid':'low'}"><strong>${x.score}</strong><span>/100</span></div><div><h2>Nota de precisão</h2><p>Cada decisão sem ajuda recebe uma nota: melhor jogada, boa alternativa, imprecisão, erro ou erro grave. A nota resume ${x.decisions} decisão(ões) em ${x.hands} mão(s).</p></div></div><div class="grade-bar" role="img" aria-label="Distribuição das notas">${order.map(k=>x.dist[k]?`<span class="grade-${k}" style="flex:${x.dist[k]}"></span>`:'').join('')}</div><div class="grade-legend">${order.map(k=>`<span><i class="grade-${k}"></i>${C.GRADES[k].label} <b>${x.dist[k]}</b></span>`).join('')}</div><div class="metric-row"><span>EV estimado perdido em decisões com preço</span><strong>${x.loss?'−'+bb(x.loss):bb(0)} <small>${x.priced} decisão(ões)</small></strong></div><div class="metric-row"><span>Perda estimada a cada 100 mãos</span><strong>${x.per100?'−'+bb(x.per100):bb(0)}</strong></div><div class="accuracy-tables"><table><caption>Por rodada</caption><thead><tr><th scope="col">Rodada</th><th scope="col">Decisões</th><th scope="col">Nota</th><th scope="col">Desvios</th><th scope="col">EV</th></tr></thead><tbody>${x.streets.map((b,i)=>b.n?row(E.STREETS[i],b):'').join('')}</tbody></table><table><caption>Por posição</caption><thead><tr><th scope="col">Posição</th><th scope="col">Decisões</th><th scope="col">Nota</th><th scope="col">Desvios</th><th scope="col">EV</th></tr></thead><tbody>${positions.map(p=>row(p,x.positions[p])).join('')}</tbody></table></div>${x.worst.length?`<h3>Maiores perdas de EV estimado</h3>${x.worst.map(w=>`<div class="evidence worst-row"><span>Mão ${w.hand} · ${E.STREETS[w.street]} · ${w.position}: você escolheu ${labels[w.action].toLowerCase()}; a referência sugeria ${labels[w.expected].toLowerCase()}. <b>−${bb(w.loss)}</b></span>${a('review','Revisar →','text-button',`data-number="${w.hand}"`)}</div>`).join('')}`:''}<p class="sample-note">O EV em reais só é calculado onde o modelo tem preço e equidade: pagar ou desistir depois do flop, e desistir sem custo. A equidade é estimada contra a faixa que cada adversário sugere pelas ações da mão (mãos anteriores à versão 2.7 usam mãos aleatórias). O valor é uma ordem de grandeza para priorizar estudo, não uma solução de solver.</p></section>`;}
 function current(){if(!t().hand&&t().players[0].stack>=C.minimum(t()))C.start(t());return t().hand;}
 function focusPlay(){const h=t().hand;if(!h||!window.matchMedia('(max-width: 850px), (orientation: landscape) and (max-height: 600px) and (max-width: 1000px)').matches)return;const mode=h.phase==='finished'?'finished':h.phase==='betting'&&h.actor===0?'hero':'watch',key=h.id+':'+mode;if(key===lastFocus)return;const first=lastFocus===null;lastFocus=key;if(first&&mode==='watch')return;
 requestAnimationFrame(()=>{if(document.getElementById('modal')?.open)return;const table=document.querySelector('.cash-play-grid>.cash-table:not(.cash-hand-log)');if(!table)return;const nav=document.querySelector('.site-header .nav'),navH=nav&&getComputedStyle(nav).position==='fixed'?nav.getBoundingClientRect().height:0,avail=window.innerHeight-navH-14,top=Math.max(0,table.getBoundingClientRect().top+window.scrollY-8);let y=top;
 if(window.matchMedia('(orientation: landscape) and (max-height: 600px) and (max-width: 1000px)').matches){y=top;}else if(mode==='watch'){if(window.scrollY<=top)return;}else{const el=mode==='hero'?document.querySelector('#cash-decision .raise-entry')||document.querySelector('#cash-decision .cash-basic'):(document.querySelector('.stage-cta.next-cta')||document.querySelector('.cash-result [data-do="cash-rebuy"]'));if(!el)return;y=Math.max(top,el.getBoundingClientRect().bottom+window.scrollY-avail);}
 if(Math.abs(y-window.scrollY)>4)window.scrollTo({top:y,behavior:reduced()?'auto':'smooth'});});}
 function schedule(view){clearTimeout(timer);if(view==='train')focusPlay();if(view!=='train'||paused)return;const h=current();if(t().session.closed||h.phase==='finished'||(h.phase==='betting'&&h.actor===0&&!t().spectating))return;timer=setTimeout(()=>{if(document.hidden||document.getElementById('modal').open){schedule(view);return;}C.step(t());save();render();},Math.max(30,duration()*(h.phase==='dealing'?.28:1)));}
 const xy=Array.from({length:9},(_,i)=>['var(--seat-x'+i+')','var(--seat-y'+i+')']),front=xy.map(([x,y])=>['calc('+x+' * .68 + 16%)','calc('+y+' * .68 + 15.68%)']);
 function flight(event,animate){if(!animate||!duration())return '';const fx=(seat,from,to,n,kind='')=>`<span class="cash-flight ${kind}" aria-hidden="true" style="--sx:${from[0]};--sy:${from[1]};--tx:${to[0]};--ty:${to[1]};--flight:${duration()}ms"><i class="chip mint"></i><b>${amount(n)}</b></span>`;
 if(['raise','call','blind','entry'].includes(event.type))return fx(event.seat,xy[event.seat],front[event.seat],event.amount);
 if(event.type==='ante')return fx(event.seat,xy[event.seat],['50%','39%'],event.amount);
 if(event.type==='collect')return event.amounts.map((n,i)=>n?fx(i,front[i],['50%','39%'],n):'').join('');
 if(['award','refund'].includes(event.type))return fx(event.seat,['50%','39%'],xy[event.seat],event.amount,'winning');
 if(event.type==='button'){const from=xy[(t().dealer+8)%9],to=xy[t().dealer];return `<span class="cash-flight button-flight" aria-hidden="true" style="--sx:${from[0]};--sy:${from[1]};--tx:${to[0]};--ty:${to[1]};--flight:${duration()}ms">D</span>`;}return '';}
 function eventText(e){if(!e)return 'Preparando a mesa';const name=e.seat===null?'':t().players[e.seat].name;const text={button:'está no botão',entry:`pagou a entrada: ${amount(e.amount)} ${unit(e.amount)}`,ante:`pagou o ante anterior: ${amount(e.amount)} ${unit(e.amount)}`,blind:`postou ${amount(e.amount)} ${unit(e.amount)}`,fold:'desistiu',check:'pediu mesa',call:`pagou ${amount(e.amount)} ${unit(e.amount)}`,raise:`${(e.previousBet??(e.to===e.amount?0:1))===0?'apostou':'aumentou para'} ${amount(e.to)} ${unit(e.to)}${e.allIn?' · all-in':''}`,collect:'Apostas recolhidas ao pote',reveal:`${E.STREETS[e.street]} revelado`,deal:'recebeu uma carta','show-cards':'revelou suas cartas',showdown:current().showdown?'Comparando as mãos':'Mão encerrada por desistência',award:`recebeu ${amount(e.amount)} ${unit(e.amount)}`,refund:`recebeu ${amount(e.amount)} ${unit(e.amount)} de volta`,finished:'Mão encerrada'};return ['collect','reveal','showdown','finished'].includes(e.type)?text[e.type]:name+' '+(text[e.type]||'agiu');}
 function bankroll(){const table=t(),stack=table.spectating?table.session.participants.hero.cashout:table.players[0].stack,total=table.reserve+stack,net=total-(table.contributions??table.initialBankroll);return `<div class="cash-bank"><div><small>${table.session.closed||table.spectating?'Saldo devolvido':'Na mesa'}</small><strong>${amount(stack)}</strong></div><div><small>Entradas acumuladas</small><strong>${amount(table.contributions)}</strong></div><div class="${net<0?'negative':'positive'}"><small>${table.hand&&table.hand.phase!=='finished'?'Saldo líquido disponível · mão aberta':'Resultado acumulado'}</small><strong>${net>0?'+':''}${amount(net)}</strong></div><span class="bank-total">Banca total: ${amount(total)} · valores simulados</span></div>`;}
 function ruleNotice(){if(t().currencyNotice)return `<div class="method-note"><strong>Nova sessão em reais simulados.</strong><p>Sua mesa anterior foi arquivada em fichas, sem conversão. Entrada: R$ 22,00 = R$ 20,00 para jogar + R$ 2,00 para a casa.</p>${a('dismiss-rule','Entendi','text-button')}</div>`;return t().ruleNotice?`<div class="method-note rule-update" role="status"><strong>Regra corrigida: entrada paga para ver o flop.</strong><p>${t().ruleNotice.refunded?'A mão que estava em andamento foi anulada e suas devolvidas antes de redistribuir. ':''}Seu saldo e as mãos concluídas foram preservados. A calibração começa novas observações com esta regra.</p>${a('dismiss-rule','Entendi','text-button')}</div>`:'';}
 function calibration(){const n=rounds(),r=D.summarize(t());return `<section class="session-card calibration-card"><div class="session-heading"><h2>${n<10?'Conhecendo seu jogo':'Calibração contínua'}</h2><span>${n<10?n+'/10 mãos':n+' mãos observadas'}</span></div><div class="calibration-track"><span style="width:${Math.min(100,n*10)}%"></span></div><p>${n<10?'Jogue no seu ritmo. A primeira leitura aparece após dez mãos.':'Seu perfil é atualizado a cada mão. As modalidades são avaliadas separadamente.'}</p>${n>=10?a('report','Ver meu diagnóstico ↗','text-button'):''}<div class="cash-mini-stats"><span>${r.unassisted} decisões sem ajuda</span><span>10ª mão de cada ciclo: Omaha 4</span></div></section>`;}
 function liveComment(){const d=current()?.decisions?.at(-1),note=C.decisionComment(d);return note?`<section class="table-comment ${note.tone}" role="status"><strong>${safe(note.title)}</strong><p>${safe(note.text)}</p><small>Revisão da sua última decisão · referência aproximada, não veredito GTO.</small></section>`:'';}
 function profiles(){openModal('Personagens da Casa do Gui',`<p>Estes são personagens fictícios de treino. Os estilos abaixo não descrevem as pessoas reais. São 20 participantes: você e 19 personagens. Oito bots começam sentados; quem zera cede o assento ao próximo da fila entre mãos. Um personagem pode voltar com reentrada de R$ 20,00.</p><div class="profile-grid">${C.PROFILES.map(p=>`<article><h3>${safe(p.name)}</h3><strong>${safe(p.nickname)}</strong><p>${safe(p.description)}</p><small>${t().players.some(x=>x.profileId===p.id)?'Nesta mesa':'No elenco'} · perfil virtual v${p.version}</small></article>`).join('')}</div><p>Renan está na lista de ausentes e não entra no sorteio. Login por WhatsApp, modelos autorizados dos jogadores e ranking online estão planejados; o ranking atual fica neste navegador e nenhum dado é compartilhado agora.</p><p>Resenha leve, respeito à mesa, sem ataques pessoais, discriminação ou provocações políticas. Foco no jogo e na revisão das decisões.</p>`);}
 function sessionProgress(){const ss=t().session,n=Math.min(t().number,ss.maxHands),done=Math.min(t().history.length,ss.maxHands),minutes=Math.min(300,Math.round(done/ss.maxHands*300));return `<section class="session-clock" aria-label="Duração simulada da sessão"><div><strong>${ss.closed?'Mesa encerrada':t().spectating?'Acompanhando a mesa':'Noite de cash · 5 horas simuladas'}</strong><span>${done}/${ss.maxHands} mãos concluídas · ${Math.floor(minutes/60)}h${String(minutes%60).padStart(2,'0')} simuladas</span></div><progress value="${done}" max="${ss.maxHands}"></progress><small>Estimativa: 24 mãos/h. Pausas não consomem a sessão. ${ss.legacy?'Mesa anterior preservada; bots contabilizados a partir da atualização.':''}</small>${ss.rotations.length?`<p>${safe(ss.rotations.at(-1).out)} saiu · ${safe(ss.rotations.at(-1).in)} entrou com R$ 20,00.</p>`:''}</section>`;}
 function rankingView(){const rows=C.ranking([...state.cashArchives,t()]);return `<p>Ranking local de sessões encerradas. 1 XP por mão disputada + 1 XP por real inteiro de lucro líquido positivo. Prejuízo não gera bônus. XP de estudo fica separado. Bots têm estilos fictícios; esta lista não é online.</p>${rows.length?`<div class="ranking-scroll"><table class="cash-ranking"><thead><tr><th>Pos.</th><th>Participante</th><th>XP de mesa</th><th>Resultado líquido</th><th>Sessões</th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td>${i+1}</td><td>${safe(p.name)}</td><td>${p.xp}</td><td>${amount(p.net)}</td><td>${p.sessions}</td></tr>`).join('')}</tbody></table></div>`:'<p>O ranking aparece ao concluir a primeira sessão.</p>'}`;}
 function sessionResult(){const ss=t().session,hero=ss.result.rows.find(p=>p.id==='hero');return `<section class="decision-card cash-result"><span class="eyebrow">Sessão concluída · ${ss.maxHands} mãos</span><h2>Fechou a mesa.</h2><p>As fichas restantes foram contabilizadas como saldo devolvido. Valores simulados, sem saque ou pagamento real.</p><div class="session-settlement"><div><small>Saldo devolvido</small><strong>${amount(hero.cashout)}</strong></div><div><small>Total investido</small><strong>${amount(hero.invested)}</strong></div><div><small>Lucro / prejuízo líquido</small><strong class="${hero.net<0?'negative':'positive'}">${amount(hero.net)}</strong></div><div><small>XP de mesa creditado</small><strong>+${hero.xp} XP</strong></div></div><p>${hero.hands} XP de participação + ${hero.profitXP} XP de lucro. Taxas e rebuys já considerados. Este fechamento é salvo uma única vez.</p>${a('ranking','Ver ranking local','next-button')}${a('new','Abrir outra sessão','outline-btn')}${a('review','Revisar última mão','text-button')}</section>`;}
 function controls(){const h=current(),v=C.visible(t());if(t().session.closed)return sessionResult();if(h.phase==='finished'){
 const net=h.delta,win=h.payouts.filter(p=>p.type==='award'),winners=[...new Set(win.map(p=>p.seat))];return `<section class="decision-card cash-result"><div class="feedback-mark ${net>=0?'':'wrong'}">${net>=0?'✓':'↗'}</div><span class="eyebrow">Mão ${h.number} encerrada</span><h2>${net>0?'Pote recebido.':net===0?'Saldo preservado.':'Uma mão para revisar.'}</h2><div class="hand-net ${net<0?'negative':'positive'}">${net>0?'+':''}${amount(net)} <small>nesta mão</small></div>${!t().spectating&&t().players[0].stack<C.minimum(t())?`<p class="method-note">Saldo insuficiente para a entrada da próxima mão. Reentrada simulada: R$ 20,00, integralmente em fichas, sem nova taxa inicial. As perdas anteriores permanecem no gráfico.</p>${a('rebuy','Reentrar: R$ 20,00 sem taxa','next-button')}${a('watch','Sair e acompanhar a mesa','outline-btn')}`:a('next',rounds()===10?'Abrir diagnóstico e continuar →':'Próxima mão →','next-button')}${handGrades(h)}<p>${winners.length?winners.map(i=>safe(t().players[i].name)).join(', ')+(winners.length>1?' dividiram os potes.':' recebeu o pote.'):'As apostas não pagas foram devolvidas.'} A qualidade da decisão é avaliada separadamente do resultado.</p><p>Pote disputado: ${bb(C.bb(h.grossPot||0))} · taxa da casa: ${bb(C.bb(h.rake||0))}.</p>${a('review','Revisar decisões desta mão','outline-btn')}${showdown(h)}<p class="sample-note">O botão avança quando você inicia a próxima mão.</p></section>`;}
 if(!v.legal)return `<section class="decision-card waiting-card"><span class="eyebrow">${h.phase==='betting'?'Vez de '+safe(t().players[h.actor]?.name||'mesa'):h.phase==='dealing'?'Distribuição':h.phase==='settle'?'Resultado':'A mesa está em movimento'}</span><h2>${paused?'Mesa pausada.':'Observe a ação.'}</h2><p class="event-live" role="status">${safe(eventText(h.event))}</p>${a('skip','Pular animações até minha vez →','next-button')}${a('pause',paused?'▶ Retomar':'Ⅱ Pausar','text-button')}</section>`;
 const l=v.legal,s=C.publicSpot(t()),min=amount(l.minTo),max=amount(l.maxTo),initial=C.bb(C.sizing(l,h.street?Math.round((C.pot(t())+l.call)*.5)+l.call+l.already:75));
 return `<section class="decision-card cash-decision" id="cash-decision"><div class="decision-top"><span class="eyebrow">Sua vez · ${E.STREETS[h.street]}</span><span class="position-badge">${C.position(t())}</span></div><h2>${l.call?'Como você responde?':'Qual é a sua jogada?'}</h2><p>${l.call?`Pagar custa ${amount(l.call)} ${unit(l.call)}. O pote, com as apostas na mesa, tem ${bb(v.pot)}.`:(h.street===0?'Sua entrada já está paga. Você pode confirmar (check) ou aumentar.':'Você pode pedir mesa ou abrir uma aposta nesta rodada.')}</p><div class="cash-context"><span>${h.kind==='omaha'?(C.potLimited(h)?'Omaha · limite do pote':'Omaha · pós-flop sem limite'):'Hold’em · sem limite'}</span><span>${s.opponents} adversário(s) ativo(s)</span></div>${spotStrip(s)}<div class="actions cash-basic">${a('play','× <b>Desistir</b><span>Encerrar sua participação</span>','action','data-value="fold"')}${a('play',l.call?`= <b>Pagar</b><span>${amount(l.call)} ${unit(l.call)}${l.call===l.stack?' · all-in':''}</span>`:(h.street===0?'✓ <b>Confirmar</b><span>Entrada já paga · check</span>':'− <b>Mesa</b><span>Sem aposta nesta rodada</span>'),'action',`data-value="${l.call?'call':'check'}"`)}</div>${l.raise?`<div class="raise-control"><label for="cash-raise">${h.currentBet?'Aumentar para':'Apostar'} <span>Total nesta rodada · múltiplos de R$ 0,25</span></label><div class="raise-entry"><input id="cash-raise" type="number" min="${C.bb(l.minTo)}" max="${C.bb(l.maxTo)}" step="0.25" value="${initial}" inputmode="decimal"><button data-do="cash-play" data-value="raise" class="next-button">${h.currentBet?'Aumentar':'Apostar'} ↗</button></div><div class="sizing-buttons">${[.33,.5,.75,1].map(f=>a('size',Math.round(f*100)+'% pote','size-button',`data-fraction="${f}"`)).join('')}${l.allIn?a('size','Tudo (all-in)','size-button','data-fraction="all"'):''}</div><small>De ${min} a ${max}${C.potLimited(h)?' · limite do pote':''}. Apostas em passos de R$ 0,25; all-in pode usar saldo exato. ${l.minTo<l.fullMinTo?'All-in curto: não reabre aumento para quem já agiu.':''}</small></div>`:''}${a('hint','ⓘ Consultar referência (marca ajuda)','text-button')}<p class="model-tag">${rounds()<10?'Avaliação inicial · feedback ao encerrar a mão':'Treino contínuo · confira o raciocínio após a mão'}</p></section>`;}
 function table(){const h=current(),v=C.visible(t()),key=h.id+':'+h.event?.id,animate=key!==lastEvent;lastEvent=key;
 const atmosphere=E.ATMOSPHERES[t().config.atmosphere],backs=n=>`<div class="seat-cards">${Array.from({length:n},()=>'<span class="card-back"></span>').join('')}</div>`;
 const seats=v.players.slice(1).map(p=>`<div style="left:${xy[p.seat][0]};top:${xy[p.seat][1]}" class="seat pos-${p.seat} ${p.folded&&!p.cards?'folded':''} ${p.cards?'cards-revealed':''} ${animate&&h.event.type==='show-cards'&&h.event.seat===p.seat?'turning-cards':''} ${h.actor===p.seat?'active-player attacking':''}"><span class="seat-avatar" aria-hidden="true">${safe(p.name[0])}</span>${p.cards?cards(p.cards,'small'):backs(p.dealt)}<div class="seat-label"><b>${p.position}</b><small>${bb(p.stack)}</small></div>${p.seat===v.dealer?'<span class="dealer">D</span>':''}<div class="fold-text" title="${safe(p.name)}">${safe(p.name)}${p.folded?' · DESISTIU':p.allIn?' · TUDO':''}</div>${['award','refund'].includes(h.event.type)&&h.event.seat===p.seat?`<span class="stack-change">+${amount(h.event.amount)}</span>`:''}</div>`).join('');
 const wagers=v.players.map(p=>p.wager?`<span style="left:${front[p.seat][0]};top:${front[p.seat][1]}" class="cash-wager wager-${p.seat}"><i class="chip mint"></i>${bb(p.wager)} ${unit(C.money(p.wager))}</span>`:'').join('');
 const hero=v.players[0],active=!t().spectating&&h.phase==='betting'&&h.actor===0;
 return `${sessionProgress()}<div class="main-grid cash-grid cash-play-grid"><section class="table-panel cash-table" aria-label="Mesa cash game"><div class="table-top"><div class="table-caption"><span class="status-dot"></span><strong>${h.kind==='omaha'?'Omaha 4 · Casa do Gui':'Hold’em · 9 jogadores'}</strong><span>Mão ${h.number}</span></div><span class="street-badge">${h.phase==='finished'?'Encerrada':E.STREETS[h.street]}</span></div><div class="poker-stage cash-stage ${h.kind==='omaha'?'cash-omaha':''} ${hero.folded&&h.phase!=='finished'?'hero-folded':''}"><div class="felt"><div class="felt-pattern"></div><div class="table-watermark"><span>♠</span>MESA 10<small>CASH LAB</small></div></div>${seats}${wagers}<div class="board-area"><div class="pot"><span class="chip mint"></span><div><small>NO CENTRO</small><span class="pot-value">${bb(v.centerPot)} </span></div></div><div class="cash-board cards">${v.board.map((c,i)=>cards([c],'mini').replace('<div class="cards">',`<div class="${animate&&h.event.type==='reveal'&&i===v.board.length-1?'reveal-card':''}">`)).join('')}${Array.from({length:5-v.board.length},()=>'<span class="ghost-card"><i>♠</i></span>').join('')}</div><div class="board-caption">${h.kind==='omaha'?'2 da mão + 3 da mesa':'TOTAL COM APOSTAS: '+bb(v.pot)+''}</div>${h.phase==='finished'?(!t().session.closed&&(t().spectating||t().players[0].stack>=C.minimum(t()))?a('next',rounds()===10?'Abrir diagnóstico →':'Próxima mão →','stage-cta next-cta'):''):(!v.legal?a('skip','Pular até minha vez ⏭','stage-cta'):'')}</div><div class="hero ${active?'hero-active':''}"><div class="hero-topline">${t().spectating?safe(hero.name):active?'Sua vez':hero.folded?'Você desistiu':'Você · '+hero.position}</div><div class="${animate&&h.event.type==='deal'&&h.event.seat===0?'new-hole-card':''}">${hero.cards.length?cards(hero.cards):'<div class="empty-hole">♠</div>'}</div><div class="hero-label"><span class="hero-indicator"></span><b>${t().spectating?safe(hero.name):'VOCÊ'} · ${hero.position}</b><span>${bb(hero.stack)}</span></div>${v.dealer===0?'<span class="dealer">D</span>':''}${['award','refund'].includes(h.event.type)&&h.event.seat===0?`<span class="stack-change">+${amount(h.event.amount)}</span>`:''}</div>${flight(h.event,animate)}</div><div class="cash-table-status" role="status">${safe(eventText(h.event))}</div></section><aside class="side-stack" aria-label="Sua decisão e leitura da mesa">${controls()}${liveComment()}${calibration()}${opponentHUD()}${gtoTips()}<div class="note-card"><h3>Entrada obrigatória para disputar o flop</h3><p>O dealer coloca R$ 0,25 no Hold’em ou R$ 0,50 no Omaha. Os demais precisam pagar, aumentar ou desistir. No Omaha, o dealer inicia a ação pré-flop; somente o pré-flop tem limite do pote. Um ciclo tem 9 mãos de Hold’em e 1 de Omaha. Se houver aumento, todos precisam igualar ou ficar all-in. O dealer não paga duas vezes: sua entrada já conta. Não há small blind nem big blind nesta mesa. Os valores são simulados. Potes disputados acima de R$ 10,00 pagam 5% para a casa; R$ 10,00 exatos não pagam. Apostas devolvidas ficam fora do cálculo.</p></div></aside><section class="table-panel cash-table cash-hand-log" aria-label="Andamento da mão"><div class="atmosphere-strip">${a('settings',`${atmosphere.icon} ${atmosphere.name} ⌄`,'text-button')}<span class="live-pressure">Blind: ${h.kind==='omaha'?bb(C.bb(C.opening(h))):'R$ 0,25'} · dealer paga</span></div><div class="table-bottom"><div class="street-track">${E.STREETS.map((s,i)=>`<span class="${i===h.street?'current':''}">${s}</span>`).join('')}</div><label class="speed-label">Animação <select id="cash-speed" aria-label="Velocidade das animações">${[['slow','Lenta'],['normal','Normal'],['fast','Rápida'],['off','Sem animação']].map(([k,l])=>`<option value="${k}" ${state.prefs.cashSpeed===k?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="hand-radar"><div class="radar-heading"><span class="eyebrow">Rastro da mão</span><span>Ações observadas</span></div><ol class="action-trail">${h.events.filter(e=>!['deal','reveal','button','finished','collect'].includes(e.type)).slice(-5).map(e=>`<li><span class="event-dot"></span><span><small>${E.STREETS[e.street]}</small>${safe(eventText(e))}</span></li>`).join('')}</ol></div></section></div><div class="cash-below"><div class="page-top"><div><div class="eyebrow">Casa do Gui · treino virtual</div><h1>Jogue. Reveja. Evolua.</h1><p>Decisões melhores começam com uma leitura honesta do seu jogo.</p></div><div>${a('profiles','♠ Personagens')}${a('ranking','Ranking local')}${a('new','↻ Nova mesa')}</div></div>${ruleNotice()}${bankroll()}<p class="sponsor-note">Apoios da arte: marcotulio.pro · corretor de imóveis | iGUi Piscinas | Sankhya | LD Celulose</p></div>`;}
 function opponentHUD(){const rows=D.opponents(t(),current().kind);return `<section class="opponent-hud"><span class="eyebrow">Pulso da mesa · ${current().kind==='omaha'?'Omaha':'Hold’em'} · pós-flop</span>${rows.map(p=>`<div class="pulse-row"><b>${safe(p.name)}</b><span class="meter"><span style="width:${Math.round((p.frequency||0)*100)}%"></span></span><small>${pct(p.frequency)} <em>em ${p.sample}</em></small></div>`).join('')}<p>Apostas ÷ (apostas + checks). Amostras pequenas não definem um estilo.</p></section>`;}
 function showdown(h){const board=h===t().hand?h.board.slice(0,h.visible):h.board||[],rows=h.revealed||(h===t().hand?C.revealedHands(t()):[]);if(!rows.length)return '';return `<section class="showdown-review"><div class="showdown-heading"><span class="eyebrow">${h.showdown?'Showdown · cartas abertas':'Cartas abertas · fim da mão'}</span><span class="showdown-icon" aria-hidden="true">♠</span></div><p>${h.showdown?'Veja as cartas de todos. Quem desistiu permanece fora da disputa.':'A mão terminou por desistência. Revelamos as cartas para estudo; as rodadas que não aconteceram continuam fechadas.'}</p>${board.length?`<div class="showdown-board"><span>Mesa revelada · ${board.length} cartas</span>${cards(board,'mini')}</div>`:''}<div class="showdown-hands">${rows.map(p=>`<article class="revealed-hand ${p.won?'won':''}"><div class="revealed-heading"><strong>${safe(p.name)} <small>${safe(p.position)}</small></strong><span>${p.folded?'Desistiu':p.won?'Recebeu pote':'Na disputa'}</span></div>${cards(p.cards,'small')}<p>${p.combination?safe(p.combination.name):'Encerrada no pré-flop'}${p.folded?' · fora do pote':''}</p>${p.combination?`<details><summary>Ver melhor combinação</summary>${cards([...p.combination.holeUsed,...p.combination.boardUsed],'mini')}<small>${p.combination.holeUsed.length} própria(s) + ${p.combination.boardUsed.length} da mesa${h.showdown?'':' · nas cartas da mesa'}</small></details>`:''}</article>`).join('')}</div></section>`;}
 function review(h=t().hand){const rows=h.decisions||[];openModal('Revisão da mão '+h.number,`${showdown(h)}<p>Compare o raciocínio com a referência didática. Ganhar ou perder não determina o acerto.</p>${rows.length?rows.map((d,i)=>{const c=d.context,g=C.grade(d),m=C.spotMetrics(c),ev=C.callEV(d),extra=d.action==='raise'&&d.to&&c.street>0?(d.to-(c.already||0)-(c.toCall||0))/((c.pot||0)+(c.toCall||0)):null;
  return `<section class="decision-review review-${d.assisted?'assisted':g.key}"><span class="eyebrow">${E.STREETS[c.street]} · decisão ${i+1}${d.assisted?' · com ajuda':''}</span><h3>${d.assisted?(d.correct?'✓ Dentro da referência':'↗ Ponto para estudar'):gradeChip(g)}</h3><div class="review-cards">${cards(c.cards,'small')}${c.board&&c.board.length?`<span class="review-board">${cards(c.board,'small')}</span>`:''}</div><p>Sua escolha: <strong>${labels[d.action]}</strong>${d.to?' para '+bb(d.to)+'':''}. Referência: ${labels[d.expected]}${(d.accepted||[]).length>1?' (também aceito: '+d.accepted.filter(k=>k!==d.expected).map(k=>labels[k].toLowerCase()).join(', ')+')':''}.</p>${typeof d.equity==='number'&&c.toCall>0&&d.price>0?`<div class="eq-meter" role="img" aria-label="Equidade estimada ${pct(d.equity)}; preço ${pct(d.price)}"><span class="eq-fill ${d.equity>=d.price?'above':'below'}" style="width:${Math.round(d.equity*100)}%"></span><i class="eq-mark" style="left:${Math.min(100,Math.round(d.price*100))}%"></i></div><div class="eq-caption"><span>Equidade estimada <b>${pct(d.equity)}</b></span><span>Preço <b>${pct(d.price)}</b></span>${ev!==null?`<span>EV estimado de pagar <b class="${ev<0?'negative':'positive'}">${ev>0?'+':ev<0?'−':''}${bb(Math.abs(ev))}</b></span>`:''}</div>`:typeof d.equity==='number'?`<div class="eq-caption"><span>Equidade estimada <b>${pct(d.equity)}</b></span></div>`:''}${Array.isArray(d.ranges)&&d.ranges.length?`<div class="range-read"><span class="eyebrow">Faixa estimada dos adversários</span><div>${d.ranges.map((r,k)=>`<span title="Parte das mãos possíveis que combina com o que este adversário fez"><i style="width:${Math.max(6,Math.round(r*100))}%"></i><b>${d.villains&&d.villains[k]?safe(d.villains[k])+' · ':''}${r>=.995?'qualquer mão':'≈ '+Math.max(1,Math.round(r*100))+'% das mãos'}</b></span>`).join('')}</div><small>Quanto menor a faixa, mais forte a mão média. Estimativa pelas ações públicas, sem cartas ocultas.</small></div>`:''}${spotStrip(c)}${m&&m.mdf!==null?`<p class="review-note">MDF ${pct(m.mdf)}: contra esta aposta, uma faixa equilibrada continua com pelo menos essa fração das mãos para não dar lucro automático a blefes. Vale para a sua faixa inteira, não para uma mão isolada.</p>`:''}${extra!==null&&extra>0?`<p class="review-note">Sua aposta: ${pct(extra)} do pote. ${m&&m.texture?m.texture.sizing:''}</p>`:''}<p>${safe(d.reason)}</p><small>Naquele momento: pote ${bb(c.pot)} · para pagar ${bb(c.toCall)}.</small></section>`;}).join(''):'<p>A mão terminou sem uma decisão sua. Ela conta como experiência de mesa, mas não como evidência de estratégia.</p>'}`);}
 function graph(){const data=(t().ledger||[{net:-200}]).map(x=>x.net/100),lo=Math.min(0,...data)-1,hi=Math.max(0,...data)+1,y=v=>130-(v-lo)/(hi-lo)*110,x=i=>10+i/Math.max(1,data.length-1)*620,points=data.map((v,i)=>`${x(i)},${y(v)}`).join(' '),last=data.at(-1);return `<figure class="bank-graph"><figcaption>Lucro e prejuízo líquido <span>${bb(last)}</span></figcaption><svg viewBox="0 0 640 155" role="img" aria-label="Resultado líquido: ${bb(last)}; inclui taxas e reentradas"><path d="M10 ${y(0)}H630" stroke="#a9b8b0" stroke-dasharray="5 5"/><text x="12" y="${y(0)-4}" fill="#cbd5ce" font-size="10">R$ 0,00</text><polyline points="${points}" fill="none" stroke="${last<0?'#f6a59b':'#b4e8a8'}" stroke-width="3"/><circle cx="${x(data.length-1)}" cy="${y(last)}" r="4" fill="#e7c584"/></svg><p>Somente mãos encerradas e entradas. Começa em −R$ 2,00. Saldo menos todas as entradas; taxas já descontadas. Reentradas não viram lucro. Valores simulados.</p><details><summary>Ver resultados por movimento</summary><ol>${(t().ledger||[]).map(e=>`<li>${e.type==='hand'?'Mão '+e.hand:e.type==='rebuy'?'Reentrada':'Entrada inicial'}: ${amount(e.net)}</li>`).join('')}</ol></details></figure>`;}
 function gtoTips(){const tips=[['Preço para pagar','No river, sem outras apostas, compare o custo para pagar com o pote final líquido de rake. Exemplo: R$ 2 para disputar R$ 12 brutos exige cerca de 17,5% de equidade após taxa de R$ 0,60.'],['Faixa de mãos e posição','Pense nas mãos possíveis do adversário, não em uma carta isolada. Agir depois oferece informação; tabelas de outra estrutura não são uma solução exata para esta mesa.'],['Valor e blefe','Ao apostar por valor, identifique mãos piores que pagariam. Um blefe precisa fazer mãos melhores desistirem; não existe uma frequência universal válida em toda situação.'],['Frequência mínima de defesa (MDF)','Contra uma aposta, MDF = pote antes da aposta ÷ (pote + aposta). Contra meio pote, cerca de 67% da sua faixa precisa continuar para que blefes não lucrem sozinhos. É uma medida da faixa inteira, e contra quem blefa pouco é correto defender menos.'],['SPR: saldo sobre o pote','Divida seu saldo pelo pote. Com SPR baixo (até 3), par alto e dois pares aceitam ir até o fim. Com SPR alto (acima de 10), só mãos muito fortes querem um pote grande.'],['Textura e tamanho da aposta','Board seco, como K-7-2 de naipes variados, favorece apostas pequenas e frequentes. Board coordenado, como 9-8-7 com dois naipes iguais, pede apostas maiores com menos mãos. O tamanho acompanha a textura.'],['Pense em faixas, não em uma mão','Cada ação reduz as mãos possíveis de um adversário. Quem aumentou antes do flop e apostou de novo representa poucas mãos, e mais fortes. Compare sua mão com essa faixa, não com uma mão qualquer.'],['Resultado não é decisão','Uma boa decisão pode perder. Reveja o que você sabia na hora; não use as cartas reveladas depois para justificar a jogada.']];const tip=tips[(t().number-1)%tips.length];return `<section class="note-card"><h3>Princípio de GTO · ${tip[0]}</h3><p>${tip[1]}</p><small>Fundamento para estudo; não é recomendação de solver para esta mesa.</small><details><summary>Termos da mesa e referências</summary><p>Mesa = check; pagar = call; desistir = fold; aumentar = raise; tudo = all-in; abertura das cartas = showdown; taxa da casa = rake. Faixa de mãos = range; banca = bankroll.</p><a href="https://blog.gtowizard.com/what-are-pot-odds-in-poker/" target="_blank" rel="noopener">GTO Wizard: preço para pagar</a> · <a href="https://www.pokerstars.com/pt-BR/poker/terms/" target="_blank" rel="noopener">Glossário PokerStars</a></details></section>`;}
 function report(){if(ai.note&&ai.hands!==rounds())ai={status:'idle'};const r=D.summarize(t()),om=D.summarize(t(),'omaha'),metrics=[['Mãos Hold’em',r.hands],['Decisões sem ajuda',r.unassisted],['Dentro da referência',pct(r.accuracy)],['Mãos Omaha',om.hands]];return `<div class="page-top"><div><div class="eyebrow">Seu jogo em revisão</div><h1>${r.calibrated?'Sua leitura inicial está aqui.':'Vamos conhecer seu jogo.'}</h1><p>${r.confidence}. ${r.calibrated?'O diagnóstico continua evoluindo.':'Complete dez mãos para abrir as prioridades de treino.'}</p></div>${a('back','← Voltar à mesa')}</div>${t().ruleStart?'<p class="method-note">Histórico anterior preservado. O diagnóstico abaixo considera apenas mãos jogadas após a correção da entrada.</p>':''}${bankroll()}<div class="stat-grid">${metrics.map(([k,v])=>`<div class="stat-box"><strong>${v}</strong><span>${k}</span></div>`).join('')}</div>${graph()}${accuracyPanel()}${r.calibrated?`<div class="cash-priorities">${(r.priorities.length?r.priorities.slice(0,3):r.groups.slice(0,2)).map((g,i)=>`<article class="content-panel"><span class="eyebrow">${g.misses?'Prioridade '+(i+1):'Continuar observando'}</span><h2>${g.title}</h2><p>${g.opportunities?`${g.misses} desvio(s) em ${g.opportunities} decisão(ões) sem ajuda.`:'Ainda faltam oportunidades para avaliar este ponto.'}</p><p>${g.tip}</p>${g.evidence.map(e=>`<div class="evidence">Mão ${e.hand} · ${E.STREETS[e.street]} · ${e.position}: você escolheu ${labels[e.action].toLowerCase()}; a referência sugeria ${labels[e.expected].toLowerCase()}.</div>`).join('')}<p class="training-goal"><strong>Próxima meta:</strong> ${g.goal}</p>${g.examples.length?a('study','Praticar minhas decisões →','next-button',`data-key="${g.key}"`):a('back','Criar mais observações →','outline-btn')}</article>`).join('')}</div>`:`<div class="content-panel"><h2>${r.calibrationHands}/10 mãos observadas</h2><p>Ainda não há base para um diagnóstico. A calibração registra decisões; não treina um novo modelo de IA nem promete identificar seu estilo em dez mãos.</p>${a('back','Continuar calibração →','next-button')}</div>`}<div class="coach-layout cash-analysis"><section class="content-panel"><span class="eyebrow">Comportamentos observados · Hold’em</span><h2>Frequências com contexto.</h2><div class="metric-row"><span>Entrou voluntariamente (VPIP)</span><strong>${r.preflopHands?pct(r.vpip/r.preflopHands):'—'} <small>${r.vpip}/${r.preflopHands}</small></strong></div><div class="metric-row"><span>Aumentou pré-flop (PFR)</span><strong>${r.preflopHands?pct(r.pfr/r.preflopHands):'—'} <small>${r.pfr}/${r.preflopHands}</small></strong></div><div class="metric-row"><span>Apostas / ações pós-flop</span><strong>${r.postflopActions?pct(r.aggression/r.postflopActions):'—'}</strong></div><p>A entrada obrigatória do dealer não entra no VPIP. Esta amostra não mede seu desempenho em mesas reais. As comparações usam heurísticas e equidade contra faixas estimadas pelas ações de cada adversário na mão, com preço ajustado ao rake estimado, sem estimar a faixa que pagaria.</p><p><strong>Omaha separado:</strong> ${om.unassisted} decisões sem ajuda; ${pct(om.accuracy)} dentro da referência. Use exatamente 2 cartas próprias e 3 da mesa.</p><p><strong>Banca:</strong> entrada de R$ 22,00: R$ 20,00 para jogar e R$ 2,00 para a casa. ${t().rebuyCount} reentrada(s). Cada reentrada acrescenta R$ 20,00 às fichas e ao total investido, sem nova taxa e sem apagar perdas.</p></section><section class="content-panel"><span class="eyebrow">Segunda leitura opcional</span><h2>Revisão com Gemini.</h2><p>Envie apenas contagens e decisões resumidas da simulação. Não são enviadas cartas ocultas, saldo real ou dados de outros aplicativos.</p>${ai.note?Object.entries({summary:'Leitura inicial',opponentRead:'Leitura dos adversários',adjustment:'Ajuste para estudar',exercise:'Exercício',caveat:'Limites'}).map(([k,l])=>`<div class="ai-response"><h3>${l}</h3><p>${safe(ai.note[k])}</p></div>`).join(''):''}${ai.error?`<p role="status" class="method-note">${safe(ai.error)}</p>`:''}${a('ai',ai.status==='loading'?'Consultando…':'Analisar meu diagnóstico com Gemini','next-button',!r.calibrated||ai.status==='loading'?'disabled':'')}<p class="privacy-note">A consulta é enviada ao Google somente ao clicar. O Free Tier tem cotas e pode usar o conteúdo para melhorar produtos. O coach local funciona sem chave. Não há garantia de lucro.</p></section></div>`;}
 function history(){return `<div class="page-top"><div><div class="eyebrow">Evolução da mesa</div><h1>O resultado conta uma parte.</h1><p>Reveja as decisões e acompanhe o saldo acumulado.</p></div>${a('back','← Mesa')}</div>${bankroll()}${graph()}<section class="content-panel"><h2>Ranking local</h2>${rankingView()}</section><div class="history-list">${[...t().history].reverse().map(h=>`<article class="history-row"><div><strong>Mão ${h.number} · ${h.kind==='omaha'?'Omaha 4':h.position+' · Hold’em'}</strong><small>${h.decisions.length} decisão(ões) · saldo após a mão: ${bb(h.stack)}</small></div><b class="${h.delta<0?'negative':'positive'}">${h.delta>0?'+':''}${bb(h.delta)}</b>${a('review','Revisar →','outline-btn',`data-number="${h.number}"`)}</article>`).join('')||'<div class="content-panel"><p>Conclua sua primeira mão para iniciar o histórico.</p></div>'}</div>${state.cashArchives.length?`<section class="content-panel archived-tables"><h2>Mesas anteriores preservadas</h2>${state.cashArchives.map((x,i)=>`<p>Mesa ${i+1}: ${x.history.length} mãos · saldo final ${x.currencyVersion?amount(x.session?.result?.rows.find(p=>p.id==='hero')?.cashout??(x.reserve+(x.spectating?x.session.participants.hero.cashout:x.players[0].stack))):C.bb(x.reserve+x.players[0].stack)+' fichas (versão anterior)'}.</p>`).join('')}</section>`:''}${a('rebuy-confirm','Reentrar R$ 20,00 sem taxa','outline-btn',t().session.closed||t().spectating||(t().hand&&t().hand.phase!=='finished')?'disabled':'')}<p class="sample-note">Reentradas disponíveis entre mãos; não contam como lucro.</p>${a('legacy','Ver histórico dos exercícios anteriores','text-button')}`;}
 function charts(){const map={'UTG+1':'UTG','UTG+2':'UTG',MP:'UTG','MP+1':'HJ',LJ:'HJ'},range=map[chartSeat]||chartSeat,stats=E.rangeStats(range),inside=E.recommended(range,chartHand)==='raise',mine=D.heroRange([...state.cashArchives.filter(x=>x&&x.currencyVersion),t()],C,E,range),sel=mine.cells[chartHand];return `<div class="page-top"><div><div class="eyebrow">Seleção por ordem de ação</div><h1>Uma referência para entrar.</h1><p>Dealer abre com R$ 0,25 no Hold’em e R$ 0,50 no Omaha. Quem continua precisa pagar ou aumentar.</p></div></div><div class="chart-layout"><section class="content-panel"><div class="position-tabs" aria-label="Posição da tabela">${['UTG','UTG+1','UTG+2','MP','MP+1','LJ','HJ','CO','BTN'].map(p=>`<button data-do="cash-chart-pos" data-value="${p}" class="${p===chartSeat?'active':''}" aria-pressed="${p===chartSeat}">${p}</button>`).join('')}</div><div class="chart-grid" aria-label="169 classes de mãos de Texas Hold’em">${E.RANKS.map((a,i)=>E.RANKS.map((b,j)=>{const key=i===j?a+b:i<j?a+b+'s':b+a+'o',yes=E.RANGES[range].has(key),cell=mine.cells[key],ins=cell?cell.raise+cell.call:0,outs=cell?cell.fold+cell.check:0,mark=!cell?'':ins&&!yes?'leak-loose':outs&&yes&&!ins?'leak-tight':'played';return `<button class="chart-cell ${yes?'raise':''} ${i===j?'pair':''} ${chartHand===key?'selected':''} ${mark}" data-do="cash-chart-hand" data-value="${key}" aria-label="${key}: ${yes?'dentro da faixa':'fora da faixa'}${cell?`; você entrou ${ins} vez(es) e não entrou ${outs}`:''}" aria-pressed="${chartHand===key}">${key}${cell?'<i class="mine-dot" aria-hidden="true"></i>':''}</button>`;}).join('')).join('')}</div><div class="chart-legend"><span><i class="legend-dot green"></i>Dentro da faixa</span><span><i class="legend-dot"></i>Fora da faixa</span><span><i class="legend-dot mine played"></i>Você jogou conforme a faixa</span><span><i class="legend-dot mine leak-loose"></i>Entrou fora da faixa</span><span><i class="legend-dot mine leak-tight"></i>Não entrou dentro da faixa</span></div><p class="chart-description">s = mesmo naipe · o = naipes diferentes · T = 10.</p></section><aside class="content-panel chart-info"><div><span class="eyebrow">${chartSeat==='BTN'?'Dealer · último a agir':'Ordem a partir da esquerda do dealer'}</span><h2>${chartSeat}</h2><div class="big-number">${stats.percent.toLocaleString('pt-BR',{maximumFractionDigits:1})}%</div><p>${stats.combos} das 1.326 combinações possíveis nesta faixa didática.</p></div><div class="chart-inspect"><span class="eyebrow">Mão selecionada</span><strong>${chartHand}</strong><div class="answer">${inside?'Dentro da faixa de referência':'Fora da faixa de referência'}</div>${sel?`<p class="mine-line">Com você: ${sel.raise} aumento(s), ${sel.call} pagamento(s), ${sel.fold+sel.check} sem entrar.</p>`:''}<p>Estude a seleção antes de decidir entre pagar, aumentar e desistir. Uma entrada já paga permite confirmar apenas quando não existe diferença a completar.</p></div><div class="chart-mine"><span class="eyebrow">Seu jogo nesta faixa</span>${mine.total?`<div class="metric-row"><span>Mãos observadas</span><strong>${mine.total}</strong></div><div class="metric-row"><span>Entrou no pote</span><strong>${pct(mine.entered/mine.total)} <small>${mine.entered}/${mine.total}</small></strong></div><div class="metric-row"><span>Entradas fora da faixa</span><strong>${mine.outside}</strong></div><div class="metric-row"><span>Não entrou dentro da faixa</span><strong>${mine.missed}</strong></div><p>Conta só as mãos de Hold’em em que ninguém aumentou antes de você nesta posição. A referência abre ${num(stats.percent)}% das mãos.</p>`:'<p>Ainda não há mãos suas nesta posição sem aumento anterior. Jogue mais mãos para ver seu range sobre a tabela.</p>'}</div></aside></div><div class="method-note">Faixas próprias e aproximadas por ordem de ação. Posições iniciais usam a referência de UTG; MP+1 e LJ usam HJ. São aproximações de tabelas 6-max para estudo, não ranges GTO de nove jogadores. Não são ranges resolvidos para a entrada do dealer, aumentos anteriores ou stacks variáveis. Consultar a tabela durante sua vez marca a decisão como assistida.</div>`;}
 function settings(){openModal('Configurar o treino cash',`<p>Nesta mesa, o dealer abre com R$ 0,25 no Hold’em e R$ 0,50 no Omaha. Quem quiser continuar precisa pagar a entrada ou o aumento vigente. Não há small blind nem big blind.</p><p>O dealer gira a cada mão. As posições são BTN, UTG, UTG+1, UTG+2, MP, MP+1, LJ, HJ e CO, na ordem relativa ao botão.</p><h3 class="setting-section-title">Ritmo dos adversários</h3>${Object.entries(E.ATMOSPHERES).map(([k,m])=>`<label class="setting-option"><input type="radio" name="cash-mood" value="${k}" ${t().config.atmosphere===k?'checked':''}><span><strong>${m.name}</strong><small>${m.description}</small></span></label>`).join('')}<p class="modal-note">A mesa atual e seu histórico serão preservados ao abrir outra. A nova mesa começa uma nova banca simulada e calibração.</p>${a('save-settings','Salvar para a próxima mesa ✓','next-button')}${a('classic','Abrir exercícios independentes da versão anterior','text-button')}<div data-pwa-settings>${root.MesaPWA?.settingsHTML()||''}</div>`);}
 function study(){const d=studyRows[studyIndex];openModal('Treino direcionado · '+(studyIndex+1)+'/'+studyRows.length,`<span class="eyebrow">Revisão da sua mão ${d.hand} · ${E.STREETS[d.context.street]}</span><p>Refaça esta decisão com o contexto que estava disponível naquele momento. Este exercício não movimenta sua banca e não entra na calibração.</p><div class="study-cards">${cards(d.context.cards,'small')}${d.context.board.length?cards(d.context.board,'small'):''}</div><p>${d.context.position} · pote ${bb(d.context.pot)} · para pagar ${bb(d.context.toCall)}.</p>${studyAnswer===null?`<div class="actions">${['fold',d.context.toCall?'call':'check',...(d.context.canRaise?['raise']:[])].map(k=>a('study-answer',labels[k],'action',`data-value="${k}"`)).join('')}</div>`:`<div class="method-note"><strong>${d.accepted.includes(studyAnswer)?'✓ Dentro da referência':'↗ Reveja este ponto'}</strong><p>${safe(d.reason)}</p><p>Meta: ${safe(D.THEMES[d.theme].goal)}</p></div>${a('study-next',studyIndex+1<studyRows.length?'Próximo exercício →':'Concluir revisão ✓','next-button')}`}`);}
 async function askAI(){if(!navigator.onLine){toast('Sem internet. Seu diagnóstico local continua disponível.');return;}if(ai.status==='loading'||rounds()<10)return;const id=t().id,analyzedHands=rounds();ai={status:'loading'};render();try{const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),21000);let res;try{res=await fetch('/api/calibration',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(D.payload(t())),signal:controller.signal});}finally{clearTimeout(timeout);}const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.code==='quota_exceeded'?'A cota da API foi atingida. O diagnóstico local continua disponível.':body.code==='not_configured'||[404,405,501].includes(res.status)?'A revisão com IA está indisponível neste endereço. O diagnóstico local continua funcionando.':'Não foi possível receber a análise. Seu progresso está salvo; tente novamente mais tarde.');if(!body.analysis?.summary)throw new Error('Resposta de IA inválida.');if(id===t().id)ai={status:'done',note:body.analysis,hands:analyzedHands};}catch(e){if(id===t().id)ai={status:'error',error:e.name==='AbortError'?'A API demorou demais. Seu progresso está salvo.':e.message};}render();}
 function handle(action,button){if(!action.startsWith('cash-'))return false;const type=action.slice(5),h=current();
 if(type==='profiles'){profiles();}
 else if(type==='ranking')openModal('Ranking da Casa do Gui',rankingView());
 else if(type==='watch'){if(C.watch(t())){C.start(t());save();render();}}
 else if(type==='play'){if(t().spectating)return true;if(h.phase!=='betting'||h.actor!==0)return true;const value=button.dataset.value;let target;if(value==='raise'){const input=document.getElementById('cash-raise'),n=Number(input.value);if(!Number.isFinite(n)||n<C.bb(C.legal(t(),0).minTo)||n>C.bb(C.legal(t(),0).maxTo)){input.reportValidity();return true;}target=C.money(n);}try{C.act(t(),value,target);}catch(e){toast(e.message);}save();render();}
 else if(type==='size'){const l=C.legal(t(),0);if(!l)return true;const f=button.dataset.fraction;document.getElementById('cash-raise').value=C.bb(f==='all'?l.maxTo:C.sizing(l,l.already+l.call+Math.round((C.pot(t())+l.call)*Number(f))));}
 else if(type==='skip'){C.runToHero(t());save();render();}
 else if(type==='pause'){paused=!paused;render();}
 else if(type==='next'){if(t().session.closed)return true;if(!t().spectating&&rounds()===10&&t().reportSeen<10){t().reportSeen=10;host.nav('coach');}else{C.start(t());paused=false;save();render();}}
 else if(type==='back'){if(h.phase==='finished'&&rounds()===10&&t().reportSeen===10&&t().players[0].stack>=C.minimum(t()))C.start(t());host.nav('train');}
 else if(type==='report')host.nav('coach');
 else if(type==='dismiss-rule'){delete t().ruleNotice;delete t().currencyNotice;save();render();}
 else if(type==='history')host.nav('history');
 else if(type==='review')review(button.dataset.number?t().history.find(x=>x.number===Number(button.dataset.number)):h);
 else if(type==='chart-pos'){if(['UTG','UTG+1','UTG+2','MP','MP+1','LJ','HJ','CO','BTN'].includes(button.dataset.value))chartSeat=button.dataset.value;render();}
 else if(type==='chart-hand'){chartHand=button.dataset.value;render();}
 else if(type==='settings')settings();
 else if(type==='save-settings'){state.prefs.cashConfig={rule:'button',atmosphere:document.querySelector('input[name="cash-mood"]:checked').value};save();document.getElementById('modal').close();toast('Configuração salva. Use Nova mesa para aplicar.');render();}
 else if(type==='new')openModal('Abrir outra mesa?',`<p>A mesa atual será arquivada com o saldo e o histórico. A nova começa com R$ 20,00 na mesa e R$ 2,00 de taxa inicial, custo total R$ 22,00. ${h.phase!=='finished'?'A mão em andamento será guardada como incompleta.':''}</p>${a('new-confirm','Arquivar e abrir nova mesa','next-button')}`);
 else if(type==='new-confirm'){state.cashArchives.push(t());state.cash=C.make(state.prefs.cashConfig||t().config);ai={status:'idle'};document.getElementById('modal').close();paused=false;host.nav('train');}
 else if(type==='rebuy-confirm')openModal('Reentrar R$ 20,00?',`<p>Acrescenta R$ 20,00 às fichas e ao total investido. Não cobra novamente os R$ 2,00; o resultado líquido é preservado.</p>${a('rebuy','Confirmar reentrada','next-button')}`);
 else if(type==='rebuy'){if(C.rebuy(t())){document.getElementById('modal').close();C.start(t());save();host.nav('train');}}
 else if(type==='hint'){if(h.actor!==0||h.phase!=='betting')return true;h.assisted=true;const s=C.publicSpot(t()),ref=C.reference(s);save();openModal('Referência didática',`<p><strong>${labels[ref.expected]}</strong></p><p>${safe(ref.reason)}</p><p class="modal-note">Esta decisão foi marcada como assistida. A recomendação não é uma solução GTO.</p>`);}
 else if(type==='study'){studyRows=D.study(t(),button.dataset.key);studyIndex=0;studyAnswer=null;studyScore=0;if(studyRows.length)study();}
 else if(type==='study-answer'){if(studyAnswer!==null)return true;studyAnswer=button.dataset.value;if(studyRows[studyIndex].accepted.includes(studyAnswer))studyScore++;study();}
 else if(type==='study-next'){if(++studyIndex<studyRows.length){studyAnswer=null;study();}else openModal('Revisão concluída',`<p>${studyScore} de ${studyRows.length} respostas dentro da referência. Na próxima mão de cash, aplique a meta do exercício antes de decidir.</p>${a('study-close','Voltar ao diagnóstico','next-button')}`);}
 else if(type==='study-close'){document.getElementById('modal').close();host.nav('coach');}
 else if(type==='ai')askAI();
 else if(type==='classic'){document.getElementById('modal').close();host.nav('classic');}
 else if(type==='legacy')host.nav('legacy-history');
 return true;
 }
 root.matchMedia?.('(orientation: landscape)').addEventListener?.('change',()=>{lastFocus=null;focusPlay();});
 document.addEventListener('change',e=>{if(e.target.id==='cash-speed'){state.prefs.cashSpeed=e.target.value;save();render();}});
 return {table,report,history,charts,settings,schedule,handle,review,pause:()=>{paused=true;clearTimeout(timer);}};
};
})(window);
